import argparse
import csv
import json
from datetime import date


def parse_date(value):
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise argparse.ArgumentTypeError("date must be in YYYY-MM-DD format")


def build_report(filename, since=None):
    rows = []
    total_revenue = 0
    total_tax = 0
    by_region = {}
    by_product = {}

    with open(filename, newline="") as sales_file:
        reader = csv.reader(sales_file)
        next(reader, None)
        for row in reader:
            if len(row) < 5:
                continue
            try:
                sale_date = date.fromisoformat(row[0])
                units = int(row[3])
                unit_price = float(row[4])
            except (ValueError, TypeError):
                continue
            if since is not None and sale_date < since:
                continue

            amount = units * unit_price
            if units >= 50:
                amount -= amount * 0.1
            elif units >= 10:
                amount -= amount * 0.05

            region = row[1]
            if region == "north":
                tax = amount * 0.07
            elif region == "south":
                tax = amount * 0.05
            elif region == "east":
                tax = amount * 0.06
            elif region == "west":
                tax = amount * 0.08
            else:
                tax = 0

            total_revenue += amount
            total_tax += tax
            by_region[region] = by_region.get(region, 0) + amount
            by_product[row[2]] = by_product.get(row[2], 0) + amount
            rows.append(row)

    top_product = None
    top_revenue = 0
    for product, revenue in by_product.items():
        if revenue > top_revenue:
            top_product = product
            top_revenue = revenue

    return {
        "rows": len(rows),
        "total_revenue": round(total_revenue, 2),
        "total_tax": round(total_tax, 2),
        "by_region": {key: round(value, 2) for key, value in by_region.items()},
        "by_product": {key: round(value, 2) for key, value in by_product.items()},
        "top_product": top_product,
    }, top_revenue


def print_text(report, top_revenue):
    print("SALES REPORT")
    print("============")
    print("Rows: " + str(report["rows"]))
    print("Total revenue: " + str(report["total_revenue"]))
    print("Total tax: " + str(report["total_tax"]))
    print("")
    print("By region:")
    for key in sorted(report["by_region"]):
        print("  " + key + ": " + str(report["by_region"][key]))
    print("")
    print("By product:")
    for key in sorted(report["by_product"]):
        print("  " + key + ": " + str(report["by_product"][key]))
    print("")
    print("Top product: " + str(report["top_product"]) + " (" + str(round(top_revenue, 2)) + ")")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("sales_csv")
    parser.add_argument("--format", choices=("text", "json"), default="text")
    parser.add_argument("--since", type=parse_date)
    args = parser.parse_args()

    report, top_revenue = build_report(args.sales_csv, args.since)
    if args.format == "json":
        print(json.dumps(report))
    else:
        print_text(report, top_revenue)


if __name__ == "__main__":
    main()
